            "overview trend report: quality must be 'pass' exactly when "
            "summary.regressed is 0"
        )
    if quality != worst["quality"]:
        raise ValueError(
            "overview trend report: quality must equal worst.quality"
        )


def load_overview_trend_report(path) -> dict:
