            "overview comparison report: source must be a JSON object"
        )
    if list(source.keys()) != list(_OVERVIEW_COMPARISON_REPORT_SOURCE_KEYS):
        raise ValueError(
            "overview comparison report: source keys must be in the order "
            "path, kind"
        )
    source_path = source["path"]
    if type(source_path) is not str:
        raise ValueError(
            "overview comparison report: source.path must be a str"
        )
    if source_path == "":
        raise ValueError(
            "overview comparison report: source.path must not be empty"
        )
    if source["kind"] != "overview_comparison":
        raise ValueError(
            "overview comparison report: source.kind must be "
            "'overview_comparison'"
        )

    summary = report["summary"]
    if not isinstance(summary, dict):
        raise ValueError(
            "overview comparison report: summary must be a JSON object"
        )
    if list(summary.keys()) != list(_OVERVIEW_COMPARISON_REPORT_SUMMARY_KEYS):
        raise ValueError(
            "overview comparison report: summary keys must be in the order "
            "count, failed, regressed_delta, passed_delta"
        )

    count = summary["count"]
    if type(count) is not int:
        raise ValueError(
            "overview comparison report: summary.count must be a non-bool int"
        )
    if not count > 0:
        raise ValueError(
            "overview comparison report: summary.count must be > 0"
        )

    failed = summary["failed"]
    if type(failed) is not int:
        raise ValueError(
            "overview comparison report: summary.failed must be a non-bool int"
        )
    if not 0 <= failed <= count:
        raise ValueError(
            "overview comparison report: summary.failed must be in [0, count]"
        )

    for name in ("regressed_delta", "passed_delta"):
        value = summary[name]
        if type(value) is not int:
            raise ValueError(
                "overview comparison report: summary."
                f"{name} must be a non-bool int"
            )

    worst = report["worst"]
    _check_overview_comparison_item(
        worst, "overview comparison report: worst: "
    )
    if not 1 <= worst["index"] <= count:
        raise ValueError(
            "overview comparison report: worst.index must be in [1, count]"
        )

    quality = report["quality"]
    if type(quality) is not str:
        raise ValueError("overview comparison report: quality must be a str")
    if quality not in _QUALITY_VALUES:
        raise ValueError(
            "overview comparison report: quality must be 'pass' or 'fail'"
        )
    expected = "pass" if failed == 0 else "fail"
    if quality != expected:
        raise ValueError(
            "overview comparison report: quality must be 'pass' exactly when "
            "summary.failed is 0"
        )
    if quality == "pass" and worst["quality"] != "pass":
        raise ValueError(
            "overview comparison report: worst.quality must be 'pass' when "
            "quality is 'pass'"
        )


